/** One line saying what a log entry changed. */
export function describe(e, group) {
  const a = e.after || {};
  const b = e.before || {};
  switch (e.action) {
    case 'addGroup':
    case 'removeGroup':
      return a.group == null ? ts('log.hidden_group') : group(a.group)?.name || `#${a.group}`;
    case 'suspend':
      return a.until ? (isForever(a.until) ? ts('log.forever') : ts('log.until', {
        date: date(a.until)
      })) + (a.reason ? ` · “${a.reason}”` : '') : '';
    case 'spammer':
      return ts('log.spammer', {
        posts: num(a.posts || 0),
        discussions: num(a.discussions || 0),
        ips: num(a.bannedIps || 0)
      }) + (a.restored ? ` · ${ts('log.restored')}` : '');
    case 'anonymize':
    case 'delete':
      return [b.username ? ts('log.was', {
        name: b.username
      }) : '', a.via === 'gdpr' ? ' · flarum/gdpr' : '', e.hashesKept ? ` · ${ts('log.hashes')}` : '', b.pruned ? ` · ${ts('log.pruned')}` : ''].join('');
    case 'export':
      return ts('log.rows', {
        count: num(a.rows || 0)
      });
    case 'signOut':
      return ts('log.sessions', {
        count: num(b.sessions || 0)
      });
    default:
      return '';
  }
}
