/** Report a finished (or queued) run, and follow a queued batch until it's done. */
export function reportRun(res, after) {
  if (res.queued) {
    const id = app.alerts.show({
      type: 'success'
    }, t('result.queued', {
      count: num(res.total)
    }));
    const poll = () => api('GET', `/batches/${res.batch}`).then(s => {
      if (s.finished) {
        app.alerts.dismiss(id);
        app.alerts.show({
          type: s.failedCount ? 'error' : 'success'
        }, t('result.done', {
          count: num(s.done),
          failed: num(s.failedCount || 0)
        }));
        after();
      } else {
        setTimeout(poll, 2000);
      }
    }).catch(() => setTimeout(poll, 4000));
    setTimeout(poll, 1500);
    return;
  }
  const failed = (res.failed || []).length;
  app.alerts.show({
    type: failed ? 'error' : 'success'
  }, failed ? t('result.done_failed', {
    count: num(res.done),
    failed: num(failed),
    names: res.failed.slice(0, 5).map(f => `${f.displayName} (${ts(`skip.${f.reason}`)})`).join(', ')
  }) : t('result.done_ok', {
    count: num(res.done)
  }));
  after();
}
